import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"最初に読む・ローカルで体験する","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md","lastUpdated":1793464466000}`),a={name:`getting-started/quickstart.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="最初に読む・ローカルで体験する" tabindex="-1">最初に読む・ローカルで体験する <a class="header-anchor" href="#最初に読む・ローカルで体験する" aria-label="Permalink to “最初に読む・ローカルで体験する”">​</a></h1><h2 id="管理画面へ招待された方" tabindex="-1">管理画面へ招待された方 <a class="header-anchor" href="#管理画面へ招待された方" aria-label="Permalink to “管理画面へ招待された方”">​</a></h2><p>インストールは不要です。招待リンクを開いて、表示名とパスキーを登録します。<a href="./../guides/accounts">ログイン・アカウント</a>へ進んでください。</p><h2 id="自分で導入する方" tabindex="-1">自分で導入する方 <a class="header-anchor" href="#自分で導入する方" aria-label="Permalink to “自分で導入する方”">​</a></h2><p>Cloudflare運用を推奨する構成として用意しています。まずローカルで画面を試し、<a href="./cloudflare">Cloudflareセットアップ</a>で自分の環境へ導入すると流れがわかりやすくなります。</p><h2 id="ローカル確認の前提" tabindex="-1">ローカル確認の前提 <a class="header-anchor" href="#ローカル確認の前提" aria-label="Permalink to “ローカル確認の前提”">​</a></h2><ul><li>Node.js 24以上とnpm</li><li>Git</li><li>パスキーに対応したブラウザと端末。最初はChromeまたはEdgeで確認してください。</li></ul><p>現行v2の確認対象ブランチを取得します。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/admin-v2-implementation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/manji6/jev-personalization.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jev-personalization</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span></span></code></pre></div><h2 id="登録する" tabindex="-1">登録する <a class="header-anchor" href="#登録する" aria-label="Permalink to “登録する”">​</a></h2><p><strong><code>http://localhost:4174/admin</code></strong> を開きます。<code>127.0.0.1</code>ではなく、このlocalhostの表記を使います。</p><p>表示名・メール・以下のローカル専用トークンを入力し、パスキーを登録します。</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local-review-only-not-a-production-token</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">本番では使わない値です</p><p>これは公開されている確認用の値です。本番のADMIN_TOKENには、秘密管理サービス等で作った独立したランダムな値を設定してください。</p></div><h2 id="どこまで実際に動くか" tabindex="-1">どこまで実際に動くか <a class="header-anchor" href="#どこまで実際に動くか" aria-label="Permalink to “どこまで実際に動くか”">​</a></h2><p>パスキー認証、DBへの保存、サイト権限、施策編集、オファー表示は実処理です。Jev判定だけを<code>local-review-stub</code>、判定値0.95のスタブにしています。JevやCloudflareへ接続せず、公開も行いません。</p><p>確認用サイトは登録済みです。施策を作り、実ページプレビューのURLに <strong><code>http://localhost:4174/demo</code></strong> を指定してください。対象パスは全許可ページまたは<code>/demo</code>にします。</p><h2 id="再起動・終了" tabindex="-1">再起動・終了 <a class="header-anchor" href="#再起動・終了" aria-label="Permalink to “再起動・終了”">​</a></h2><p>Ctrl+Cで終了します。アカウントと設定は<code>data/review.sqlite</code>に残り、再起動後も使えます。履歴が必要ならこのDBを消さないでください。</p><p>初期状態から試す場合はサーバーを停止し、別の新規DBを<code>REVIEW_DB_PATH</code>へ指定します。ポートを変える場合は<code>REVIEW_PORT</code>も指定できます。</p><p>パスキーはOriginとRP IDに結び付きます。確認途中でlocalhostを別ドメインやIPへ変えないでください。</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};